// Generates src/__buildFlags.ts from the PHONEHANDS_READ_ONLY env var at BUILD time.
// This is what makes read-only a COMPILE-TIME switch: the flag is baked into
// the built artifact, so write actions are never registered in a read-only build
// (there is no runtime flag to flip, forget, or bypass).
const fs = require("fs");
const path = require("path");

const readOnly = process.env.PHONEHANDS_READ_ONLY === "1";
const out = path.join(__dirname, "..", "src", "__buildFlags.ts");
const content =
  "// SPDX-License-Identifier: BUSL-1.1\n" +
  "// GENERATED by scripts/gen-build-flags.js — do not edit by hand.\n" +
  // No timestamp: the output must be deterministic so a plain build leaves
  // the committed file untouched (CI fails on drift).
  `// Built with PHONEHANDS_READ_ONLY=${readOnly ? "1" : "0"}\n` +
  `export const PHONEHANDS_READ_ONLY: boolean = ${readOnly};\n`;
fs.writeFileSync(out, content);
console.log(`[phonehands:core] build flags written: PHONEHANDS_READ_ONLY=${readOnly}`);
